checkBlitzGseaParams <- function(x) {
  res <- check_list_shape(
    x,
    c(
      "min_size",
      "max_size",
      "permutations",
      "anchors",
      "symmetric",
      "centre",
      "ks_test",
      "seed"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      min_size = "I1[3,)",
      max_size = "I1[4,)",
      permutations = "I1[2,)",
      anchors = "I1[2,)",
      symmetric = "B1",
      centre = "B1",
      ks_test = "B1",
      seed = "N1[0,)"
    ),
    label = "blitzGSEA params",
    hint = paste(
      "min_size and max_size must be integers (with max_size > min_size",
      "and min_size >= 3); permutations and anchors must be integers >=",
      "2; symmetric, centre and ks_test must be booleans; seed must be",
      "a non-negative double."
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  return(TRUE)
}

