      "del0_ll_tol",
      "min_ll_tol",
      "tol_p",
      "tol_f",
      "norm_from_rounded",
      "seed"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      freeze_empties = "B1",
      freeze_ambient_profile = "B1",
      init_alpha = "N1[0.1,0.9]",
      init_beta = "N1[0.1,0.9]",
      alpha_cap = "N1[0,1]",
      repulsion_strength = "N1[0,1e-3]",
      max_frac_gene_repulsion = "N1(0,1]",
