#' Check empty droplet params
#'
#' @description Checkmate extension for the output of
#' [params_sc_empty_droplets()].
#'
#' @param x The object to check.
#'
#' @returns `TRUE` if the check was successful, otherwise a
#' checkmate-style error string.
#'
#' @keywords internal
checkScEmptyDropletsParams <- function(x) {
  res <- check_list_shape(
    x,
    c(
      "method",
      "is_empty_column",
      "umi_cutoff",
      "expected_cells"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      is_empty_column = c("S1", "0"),
      umi_cutoff = c("I1[1,)", "0"),
      expected_cells = c("I1[1,)", "0")
    ),
    label = "empty droplet params"
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_choice_rules(
    x,
    list(
      method = c("supplied", "umi_cutoff", "expected_cells", "knee")
    ),
    label = "empty droplet params"
  )
  if (!isTRUE(res)) {
    return(res)
  }

  required <- switch(
    x$method,
    supplied = "is_empty_column",
    umi_cutoff = "umi_cutoff",
    expected_cells = "expected_cells",
    knee = NULL
  )
  if (!is.null(required) && is.null(x[[required]])) {
    return(sprintf("`method = '%s'` needs `%s`.", x$method, required))
  }

  return(TRUE)
}

