      "epsilon_harmony",
      "window_size",
      "k_means_iter",
      "k_means_init",
      "gemm",
      "hamerly"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      k = c("I1[1,)", "0"),
      sigma = "N+[0,)",
      theta = "N+[0,)",
      lambda = "N+[0,)",
      block_size = "N1(0,1]",
      max_iter_kmeans = "I1[1,)",
      max_iter_harmony = "I1[1,)",
      epsilon_kmeans = "N1(0,)",
