#' Check MTX IO params
#'
#' @description Checkmate extension for the output of [params_sc_mtx_io()].
#'
#' @param x The object to check.
#'
#' @returns `TRUE` if the check was successful, otherwise a
#' checkmate-style error string.
#'
#' @keywords internal
checkScMtxIOParams <- function(x) {
  res <- check_list_shape(
    x,
    c(
      "path_mtx",
      "path_obs",
      "path_var",
      "cells_as_rows",
      "has_hdr"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      cells_as_rows = "B1",
      has_hdr = "B1"
    ),
    label = "MTX IO params",
    hint = "cells_as_rows and has_hdr must be booleans."
  )
  if (!isTRUE(res)) {
    return(res)
  }

  files_ok <- purrr::map_lgl(
    c("path_mtx", "path_obs", "path_var"),
    function(n) checkmate::testFileExists(x[[n]])
  )
  if (!all(files_ok)) {
    return(paste(
      "Some of the files specified in the config for mtx ingest do not",
      "exist. Please check the provided params."
    ))
  }

  return(TRUE)
}

