#' Check Palantir params
#'
#' @description Checkmate extension for the output of [params_sc_palantir()].
#'
#' @param x The object to check.
#'
#' @returns `TRUE` if the check was successful, otherwise a
#' checkmate-style error string.
#'
#' @keywords internal
checkScPalantirParams <- function(x) {
  res <- check_list_shape(
    x,
    c(
      "n_dcs",
      "n_eigs",
      "knn",
      "num_waypoints",
      "scale_components",
      "use_early_cell_as_start",
      "max_iterations",
      "branch_prob_threshold",
      "lanczos_basis_size",
      "lanczos_max_restarts",
      "lanczos_tol",
      "k",
