      "ann_dist",
      "n_trees",
      "search_budget",
      "delta",
      "diversify_prob",
      "ef_budget",
      "extract_knn",
      "m",
      "ef_construction",
      "ef_search",
      "n_list",
      "n_probe"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      n_dcs = "I1[3,)",
      n_eigs = c("I1[3,)", "0"),
      knn = "I1[6,)",
      num_waypoints = "I1[1,)",
      scale_components = "B1",
      use_early_cell_as_start = "B1",
      max_iterations = "I1[2,)",
      branch_prob_threshold = "N1[0,1]",
      lanczos_basis_size = c("I1[1,)", "0"),
      lanczos_max_restarts = "I1[1,)",
