#' Check synthetic CellSweep params
#'
#' @description Checkmate extension for the output of
#' [params_sc_synthetic_cellsweep()].
#'
#' @param x The object to check.
#'
#' @returns `TRUE` if the check was successful, otherwise a
#' checkmate-style error string.
#'
#' @keywords internal
checkScSyntheticCellsweepParams <- function(x) {
  res <- check_list_shape(
    x,
    c(
      "n_real",
      "n_empty",
      "n_genes",
      "n_celltypes",
      "n_markers",
      "marker_weight",
      "ambient_dominance",
      "alpha_mean",
      "alpha_sd",
      "real_lib_size",
      "empty_lib_size"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      n_real = "I1[1,)",
      n_empty = "I1[30,)",
      n_genes = "I1[1,)",
      n_celltypes = "I1[1,)",
      n_markers = "I1[1,)",
      marker_weight = "N1(1,)",
      ambient_dominance = "N1[0,1]",
      alpha_mean = "N1[0.02,0.85]",
      alpha_sd = "N1[0,)",
      real_lib_size = "I1[1,)",
      empty_lib_size = "I1[1,)"
    ),
    label = "synthetic CellSweep params",
    hint = paste(
      "n_empty must be at least 30, marker_weight above 1, and the",
      "fractions within their respective ranges."
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  if (x$n_markers * x$n_celltypes > x$n_genes) {
    return("The marker gene blocks do not fit into n_genes.")
  }

  return(TRUE)
}

