#'
#' @keywords internal
assertScSyntheticCellsweepParams <- checkmate::makeAssertionFunction(
  checkScSyntheticCellsweepParams
)

#' Check synthetic data params
#'
#' @description Checkmate extension for the output of
#' [params_sc_synthetic_data()].
#'
#' @param x The object to check.
#'
#' @returns `TRUE` if the check was successful, otherwise a
#' checkmate-style error string.
#'
#' @keywords internal
checkScSyntheticDataParams <- function(x) {
  res <- check_list_shape(
    x,
    c(
      "n_cells",
      "n_genes",
      "marker_genes",
      "n_batches",
      "batch_effect_strength",
      "n_samples",
      "sample_bias"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      n_cells = "I1",
      n_genes = "I1",
      n_batches = "I1",
      n_samples = c("I1", "0")
    ),
    label = "synthetic data params",
    hint = paste(
      "n_cells, n_genes and n_batches must be integers; n_samples must",
      "be an integer or NULL."
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_choice_rules(
    x,
    list(
      batch_effect_strength = c("strong", "medium", "weak")
    ),
    label = "synthetic data params",
    hint = paste(
      "n_cells, n_genes and n_batches must be integers; n_samples must",
      "be an integer or NULL."
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- checkmate::checkList(x$marker_genes, types = "list", names = "named")
  if (!isTRUE(res)) {
    return(res)
  }
  if (!is.null(x[["sample_bias"]])) {
    res <- apply_choice_rules(
      x,
      list(sample_bias = c("even", "slightly_uneven", "very_uneven")),
      label = "synthetic data params"
    )
    if (!isTRUE(res)) {
      return(res)
    }
  }

  return(TRUE)
}

