#' Check synthetic DIALOGUE params
#'
#' @description Checkmate extension for the output of
#' [params_sc_synthetic_dialogue()].
#'
#' @param x The object to check.
#'
#' @returns `TRUE` if the check was successful, otherwise a
#' checkmate-style error string.
#'
#' @keywords internal
checkScSyntheticDialogueParams <- function(x) {
  res <- check_list_shape(
    x,
    c(
      "n_samples",
      "cells_per_sample",
      "n_cell_types",
      "n_features",
      "n_sample_features",
      "n_genes",
      "n_planted"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      n_samples = "I1[1,)",
      cells_per_sample = "I1[1,)",
      n_cell_types = "I1[2,)",
      n_features = "I1[2,)",
      n_sample_features = "I1[1,)",
      n_genes = "I1[1,)",
      n_planted = "I1[0,)"
    ),
    label = "synthetic DIALOGUE params",
    hint = paste(
      "n_cell_types and n_features must be at least 2, the remaining",
      "counts positive integers."
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  if (x$n_sample_features > x$n_features) {
    return("n_sample_features cannot exceed n_features.")
  }
  if (x$n_planted * x$n_cell_types > x$n_genes) {
    return("The planted gene blocks do not fit into n_genes.")
  }

  return(TRUE)
}

