#'
#' @keywords internal
checkScenicParams <- function(x) {
  res <- check_list_shape(
    x,
    c(
      "min_counts",
      "min_cells",
      "learner_type",
      "gene_batch_strategy",
      "gene_batch_size",
      "n_pcs",
      "n_subsample"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      min_counts = "I1[1,)",
      min_cells = "N1(0,1]",
      gene_batch_size = c("I1[1,)", "0"),
      n_pcs = "I1[1,)",
      n_subsample = "I1[1,)"
    ),
    label = "SCENIC params",
    hint = paste(
      "min_counts, n_pcs, n_subsample, min_samples_leaf and max_depth",
      "must be integers >= 1; n_features_split must be an integer >= 0;",
      "min_cells must be in (0, 1]."
