#' Check Scrublet params
#'
#' @description Checkmate extension for the output of [params_scrublet()].
#'
#' @param x The object to check.
#'
#' @returns `TRUE` if the check was successful, otherwise a
#' checkmate-style error string.
#'
#' @keywords internal
checkScScrubletParams <- function(x) {
  res <- check_list_shape(
    x,
    c(
      "log_transform",
      "mean_center",
      "normalise_variance",
      "target_size",
      "min_gene_var_pctl",
      "hvg_method",
      "loess_span",
      "clip_max",
      "n_bins",
      "binning_strategy",
      "no_pcs",
      "random_svd",
      "sparse",
      "k",
      "knn_method",
      "ann_dist",
      "n_trees",
      "search_budget",
      "delta",
      "diversify_prob",
      "ef_budget",
      "extract_knn",
      "m",
      "ef_construction",
      "ef_search",
      "n_list",
      "n_probe",
      "sim_doublet_ratio",
      "expected_doublet_rate",
      "stdev_doublet_rate",
      "n_bins_histogram",
      "manual_threshold"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      log_transform = "B1",
      mean_center = "B1",
      normalise_variance = "B1",
      target_size = "N1[0,)",
      min_gene_var_pctl = "N1[0,1]",
      loess_span = "N1(0,)",
      clip_max = c("N1(0,)", "0"),
      n_bins = "I1[1,)",
      no_pcs = "I1[1,)",
      random_svd = "B1",
      sparse = "B1",
      k = "I1[0,)",
      n_trees = "I1[1,)",
      search_budget = c("I1[1,)", "0"),
      delta = "N1[0,1]",
      diversify_prob = "N1[0,1]",
      ef_budget = c("I1[1,)", "0"),
      extract_knn = "B1",
      m = "I1[1,)",
      ef_construction = "I1[1,)",
      ef_search = "I1[1,)",
      n_list = c("I1[1,)", "0"),
      n_probe = c("I1[1,)", "0"),
      sim_doublet_ratio = "N1(0,)",
      expected_doublet_rate = "N1[0,1]",
      stdev_doublet_rate = "N1[0,1]",
      n_bins_histogram = "I1[10,)",
      manual_threshold = c("N1[0,)", "0")
    ),
    label = "Scrublet params",
    hint = paste(
      "no_pcs must be >= 1; n_bins_histogram must be >= 10; n_bins must",
      "be >= 1; min_gene_var_pctl, expected_doublet_rate and",
      "stdev_doublet_rate must be in [0, 1]; loess_span and",
      "sim_doublet_ratio must be > 0; target_size must be >= 0;",
      "log_transform, mean_center, normalise_variance and random_svd",
      "must be booleans; clip_max and manual_threshold must be NULL or",
      "positive numerics."
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_choice_rules(
    x,
    list(
      hvg_method = c("vst", "mvb", "dispersion"),
      binning_strategy = c("equal_width", "equal_frequency"),
      knn_method = c(
        "kmknn",
        "hnsw",
        "annoy",
        "nndescent",
        "ivf",
        "exhaustive"
      ),
      ann_dist = c("euclidean", "cosine")
    ),
    label = "Scrublet params",
    hint = paste(
      "no_pcs must be >= 1; n_bins_histogram must be >= 10; n_bins must",
      "be >= 1; min_gene_var_pctl, expected_doublet_rate and",
      "stdev_doublet_rate must be in [0, 1]; loess_span and",
      "sim_doublet_ratio must be > 0; target_size must be >= 0;",
      "log_transform, mean_center, normalise_variance and random_svd",
      "must be booleans; clip_max and manual_threshold must be NULL or",
      "positive numerics."
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  return(TRUE)
}

#' Assert Scrublet params
#'
#' @inheritParams checkScScrubletParams
#' @param .var.name Name of the checked object to print in assertions.
#' @param add Collection to store assertion messages. See
#' [checkmate::makeAssertCollection()].
#'
#' @returns Invisibly returns the checked object if the assertion is
#' successful.
#'
#' @keywords internal
assertScScrubletParams <- checkmate::makeAssertionFunction(
  checkScScrubletParams
)

