  res <- apply_choice_rules(
    x,
    list(
      distance_metric = c("euclidean", "manhattan", "canberra", "cosine")
    ),
    label = "SNF params",
    hint = paste(
      "k and t must be positive integers; mu must be a float in [0, 1];",
      "alpha must be a float; normalise must be a boolean."
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  return(TRUE)
}

