#' Check synthetic bulk params
#'
#' @description Checkmate extension for the output of
#' [params_synthetic_bulk_rnaseq()].
#'
#' @param x The object to check.
#'
#' @returns `TRUE` if the check was successful, otherwise a
#' checkmate-style error string.
#'
#' @keywords internal
checkSyntheticBulkParams <- function(x) {
  res <- check_list_shape(
    x,
    c(
      "num_samples",
      "num_genes",
      "module_sizes",
      "generator",
      "seed",
      "mean_exp_gamma_shape",
      "mean_exp_gamma_scale",
      "disp_intercept",
      "disp_slope",
      "noise_std",
      "factor_std",
      "factor_shape",
      "factor_scale",
      "loading_mu",
      "loading_sigma",
      "hub_percentile"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      num_samples = "I1[1,)",
      num_genes = "I1[1,)",
      module_sizes = "I*",
      seed = "I1[0,)",
      mean_exp_gamma_shape = "N1(0,)",
      mean_exp_gamma_scale = "N1(0,)",
      disp_intercept = "N1(0,)",
      disp_slope = "N1(0,)",
      noise_std = "N1[0,)",
      factor_std = "N1(0,)",
      factor_shape = "N1(0,)",
      factor_scale = "N1(0,)",
      loading_mu = "N1",
      loading_sigma = "N1(0,)",
      hub_percentile = "N1(0,1]"
    ),
    label = "synthetic bulk params",
    hint = paste(
      "num_samples, num_genes and seed must be integers; module_sizes",
      "must be an integer vector (a double vector is silently ignored",
      "downstream); hub_percentile must sit in (0, 1]; the remaining",
      "distribution parameters must be positive floats."
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_choice_rules(
    x,
    list(
      generator = c(
        "hub_modular",
        "modular",
        "non_negative_factor",
        "non_gaussian_factor"
      )
    ),
    label = "synthetic bulk params",
    hint = paste(
      "num_samples, num_genes and seed must be integers; module_sizes",
      "must be an integer vector (a double vector is silently ignored",
      "downstream); hub_percentile must sit in (0, 1]; the remaining",
      "distribution parameters must be positive floats."
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  if (sum(x[["module_sizes"]]) > x[["num_genes"]]) {
    return("The sum of `module_sizes` must not exceed `num_genes`.")
  }

  return(TRUE)
}

#' Assert synthetic bulk params
#'
#' @inheritParams checkSyntheticBulkParams
#' @param .var.name Name of the checked object to print in assertions.
#' @param add Collection to store assertion messages. See
#' [checkmate::makeAssertCollection()].
#'
#' @returns Invisibly returns the checked object if the assertion is
#' successful.
#'
#' @keywords internal
assertSyntheticBulkParams <- checkmate::makeAssertionFunction(
  checkSyntheticBulkParams
)
